//! sce_forge_runtime — algorithm and HAL library for code generated by SCE Forge.
//!
//! Implements the runtime library policy from SCE_FORGE.md Section 2.1:
//! statically linkable, no global state, no I/O. The crate is `#![no_std]`
//! so embedded targets without a heap can depend on it directly for the
//! algorithm modules (filter, interpolation, lookup, observer, timer).
//!
//! The `alloc` feature (enabled by default) pulls in the `procedure` module,
//! which provides the shared types and event-driven execution loop used by
//! generated `sce:kind="procedure"` code. Procedures inherently need a heap
//! allocator, so targets without one should disable default features.

#![no_std]

pub mod codec;
pub mod filter;
pub mod interpolation;
pub mod lookup;
pub mod observer;
pub mod timer;

// Re-export `heapless` so generated codec output can spell its bounded
// inline list type as `sce_forge_runtime::heapless::Vec<T, N>` without a
// separate dependency edge — one pinned version, owned by this runtime.
// `heapless` is `#![no_std]` and heap-free, so this does not weaken the
// crate's pure no_std no-alloc baseline.
pub use heapless;

#[cfg(feature = "alloc")]
pub mod procedure;

#[cfg(test)]
mod smoke_tests {
    use super::filter::{Debounce, LowPass, MovingAverage};
    use super::interpolation::{bilinear, linear};
    use super::lookup::lookup;
    use super::observer::{EventDomain, EventQueue, ThresholdState};
    use super::timer::{Timer, TimerCallback};
    use core::ffi::c_void;

    #[test]
    fn linear_midpoint() {
        let axis = [0.0, 1.0, 2.0, 3.0];
        let vals = [10.0, 20.0, 30.0, 40.0];
        assert!((linear(&axis, &vals, 1.5) - 25.0).abs() < 1e-12);
    }

    #[test]
    fn lookup_exact_hit_and_miss() {
        let keys: [u16; 3] = [100, 200, 300];
        let values: [u8; 3] = [1, 2, 4];
        assert_eq!(lookup(&keys, &values, 200), Some(2));
        assert_eq!(lookup(&keys, &values, 250), None);
    }

    #[test]
    fn bilinear_centre() {
        let ax = [0.0, 1.0];
        let ay = [0.0, 1.0];
        let tab = [[0.0, 1.0], [2.0, 3.0]];
        assert!((bilinear(&ax, &ay, &tab, 0.5, 0.5) - 1.5).abs() < 1e-12);
    }

    #[test]
    fn moving_average_first_sample() {
        let mut ma: MovingAverage<f64, 4> = MovingAverage::new();
        assert!((ma.update(1.0) - 1.0).abs() < 1e-12);
    }

    #[test]
    fn low_pass_first_sample_passthrough() {
        let mut lp: LowPass<f64> = LowPass::new(0.1);
        assert!((lp.update(7.0) - 7.0).abs() < 1e-12);
    }

    #[test]
    fn debounce_until_filled() {
        let mut db: Debounce<bool, 3> = Debounce::new();
        assert!(db.update(true));
        assert!(!db.update(false));
    }

    struct DummyTimer;
    impl Timer for DummyTimer {
        fn start_periodic(&mut self, _: u32, _: TimerCallback, _: *mut c_void) {}
        fn start_one_shot(&mut self, _: u32, _: TimerCallback, _: *mut c_void) {}
        fn cancel(&mut self) {}
    }

    #[test]
    fn timer_trait_object_is_usable() {
        let mut t = DummyTimer;
        let r: &mut dyn Timer = &mut t;
        r.cancel();
    }

    struct AlertDomain;
    // No `Default` impl — verifies that EventDomain does not require it.
    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    enum AlertTag {
        Low,
        High,
    }
    impl EventDomain for AlertDomain {
        type Tag = AlertTag;
    }

    #[test]
    fn threshold_and_event_queue() {
        let mut st = ThresholdState::new();
        assert!(st.enter_if(true));
        assert!(!st.enter_if(true));
        assert!(st.leave_if(true));

        let mut q: EventQueue<AlertDomain> = EventQueue::new();
        assert!(q.is_empty());
        q.push(AlertTag::High);
        q.push(AlertTag::Low);
        assert_eq!(q.len(), 2);
        assert_eq!(q.as_slice()[0].tag, AlertTag::High);
        assert_eq!(q.as_slice()[1].tag, AlertTag::Low);
    }
}
